DO $seed$ DECLARE new_release uuid; BEGIN IF NOT EXISTS (SELECT 1 FROM active_release) THEN INSERT INTO publication_release(label,source) VALUES ('Imported live defaults 2026-09-24','legacy_import') RETURNING id INTO new_release; INSERT INTO release_entry(release_id,item_id,revision_id) SELECT new_release,item.id,rev.id FROM content_item item JOIN content_revision rev ON rev.item_id=item.id AND rev.version=1 WHERE item.stable_key = ANY(ARRAY['author:legacy-1','author:legacy-2','author:legacy-3','book:prince','book:stranger','book:house','world:solitude','world:choice','world:memory','world:beginning','world:home','mood:calm','mood:think','mood:imagine','mood:change','experience:silence','experience:choice','experience:voice','experience:begin','experience:home','experience:star','experience:pause','experience:another','home_work:1','home_work:2','home_work:3','share_work:approved-podcast','share_work:approved-writing','share_work:approved-image','photo:prince','photo:stranger','photo:house','page:home','page:entry','page:books','page:podcasts','page:photos','page:worlds','page:share']); INSERT INTO active_release(singleton,release_id) VALUES (true,new_release); END IF; END $seed$;
