INSERT INTO content_revision(item_id,version,payload,note) SELECT id,1,'{"id":"silence","title":"گاهی سکوت، بلندترین پاسخ است.","short":"کمی در سکوت بمان.","minutes":3,"format":"read","question":"در سکوتِ امروزت چه چیزی شنیدی؟","paragraphs":["قرار نیست هر فاصله‌ای را با کلمه پُر کنیم. گاهی میان دو جمله، فرصتی هست که چیزی از خودمان بشنویم؛ چیزی که زیر صدای روز پنهان شده بود.","برای چند لحظه، پاسخی آماده نکن. فقط ببین کدام فکر برمی‌گردد، کدام خاطره نزدیک می‌شود و کدام خواسته هنوز آرام منتظر توست.","شاید سکوت، پایان گفت‌وگو نباشد. شاید شروع شنیدن باشد."],"audioMedia":null}'::jsonb,'import from 4009b3c70729b832ecaaa1606c49158b3267521e' FROM content_item WHERE stable_key='experience:silence' AND NOT EXISTS (SELECT 1 FROM content_revision WHERE item_id=content_item.id) ON CONFLICT (item_id,version) DO NOTHING;
INSERT INTO content_item(kind,stable_key,slug) VALUES ('experience','experience:choice','choice') ON CONFLICT (stable_key) DO NOTHING;
INSERT INTO content_revision(item_id,version,payload,note) SELECT id,1,'{"id":"choice","title":"اگر دوباره انتخاب کنی، همین آدمی؟","short":"کنار یک پرسش بمان.","minutes":3,"format":"read","question":"کدام انتخاب هنوز در تو ادامه دارد؟","paragraphs":["بعضی انتخاب‌ها با تمام‌شدن یک روز تمام نمی‌شوند. آرام وارد عادت‌هایمان می‌شوند؛ در جمله‌هایی که می‌گوییم و راه‌هایی که دیگر امتحان نمی‌کنیم.","به یکی از آن‌ها فکر کن. اگر قرار نبود از تصمیم گذشته‌ات دفاع کنی، امروز چه چیزی را متفاوت می‌دیدی؟","لازم نیست همین حالا راه تازه‌ای انتخاب کنی. گاهی دیدنِ یک امکان دیگر، خودش آغاز است."],"audioMedia":null}'::jsonb,'import from 4009b3c70729b832ecaaa1606c49158b3267521e' FROM content_item WHERE stable_key='experience:choice' AND NOT EXISTS (SELECT 1 FROM content_revision WHERE item_id=content_item.id) ON CONFLICT (item_id,version) DO NOTHING;
INSERT INTO content_item(kind,stable_key,slug) VALUES ('experience','experience:voice','voice') ON CONFLICT (stable_key) DO NOTHING;
INSERT INTO content_revision(item_id,version,payload,note) SELECT id,1,'{"id":"voice","title":"بعضی صداها در ما می‌مانند.","short":"ردّ یک صدای آشنا.","minutes":3,"format":"listen","question":"کدام صدا تو را به جایی دور می‌برد؟","paragraphs":["صدای بسته‌شدن یک در. برخورد قاشق با استکان. نامی که کسی به شیوه‌ای مخصوص صدا می‌کرد. بعضی صداها راه خانه را بهتر از ما بلدند.","چشم‌هایت را اگر خواستی ببند. دنبال خاطره نگرد؛ بگذار یک صدا خودش پیدایت کند.","به جایی که برگشتی چه می‌گویی؟ خانه، گذشته، یا بخشی از خودت که هنوز همان‌جاست؟"],"audioMedia":null}'::jsonb,'import from 4009b3c70729b832ecaaa1606c49158b3267521e' FROM content_item WHERE stable_key='experience:voice' AND NOT EXISTS (SELECT 1 FROM content_revision WHERE item_id=content_item.id) ON CONFLICT (item_id,version) DO NOTHING;
INSERT INTO content_item(kind,stable_key,slug) VALUES ('experience','experience:begin','begin') ON CONFLICT (stable_key) DO NOTHING;
INSERT INTO content_revision(item_id,version,payload,note) SELECT id,1,'{"id":"begin","title":"ادامه می‌تواند شکل دیگری داشته باشد.","short":"از یک تغییر کوچک.","minutes":3,"format":"listen","question":"کوچک‌ترین تغییری که دوست داری چیست؟","paragraphs":["برای شروع دوباره همیشه لازم نیست همه‌چیز را کنار بگذاری. گاهی کافی است پنجره‌ای را که هر روز از کنارش می‌گذری باز کنی.","یک کار کوچک را تصور کن که امروز می‌تواند فرق داشته باشد. نه برای تبدیل‌شدن به آدمی دیگر؛ برای نزدیک‌ترشدن به چیزی که واقعاً می‌خواهی.","شروع، همیشه یک اعلام بزرگ نیست. گاهی تنها یک قدم است."],"audioMedia":null}'::jsonb,'import from 4009b3c70729b832ecaaa1606c49158b3267521e' FROM content_item WHERE stable_key='experience:begin' AND NOT EXISTS (SELECT 1 FROM content_revision WHERE item_id=content_item.id) ON CONFLICT (item_id,version) DO NOTHING;
INSERT INTO content_item(kind,stable_key,slug) VALUES ('experience','experience:home','home') ON CONFLICT (stable_key) DO NOTHING;
INSERT INTO content_revision(item_id,version,payload,note) SELECT id,1,'{"id":"home","title":"خانه جایی است که خودت باشی.","short":"معنای تازه‌ی خانه.","minutes":7,"format":"read","question":"کجا لازم نیست خودت را توضیح بدهی؟","paragraphs":["نشانی بعضی خانه‌ها را نمی‌توان روی نقشه پیدا کرد. جایی‌اند میان یک آغوش، یک گفت‌وگوی بی‌تکلف و اطمینان از اینکه برای ماندن لازم نیست نقش بازی کنیم.","به آخرین باری فکر کن که جایی آسوده بودی. چه چیزی آنجا بود؟ چه چیزی نبود؟ آدم‌ها، صداها و حتی سکوت‌ها چگونه بودند؟","شاید بخشی از خانه، چیزی باشد که می‌توانیم برای دیگری بسازیم: فرصتی برای آنکه بی‌دفاع و بی‌توضیح، خودش باشد."],"audioMedia":null}'::jsonb,'import from 4009b3c70729b832ecaaa1606c49158b3267521e' FROM content_item WHERE stable_key='experience:home' AND NOT EXISTS (SELECT 1 FROM content_revision WHERE item_id=content_item.id) ON CONFLICT (item_id,version) DO NOTHING;
INSERT INTO content_item(kind,stable_key,slug) VALUES ('experience','experience:star','star') ON CONFLICT (stable_key) DO NOTHING;
INSERT INTO content_revision(item_id,version,payload,note) SELECT id,1,'{"id":"star","title":"جهان، گاهی از یک خیال شروع می‌شود.","short":"به جایی که هنوز نیست.","minutes":7,"format":"read","question":"اگر یک مرز برداشته شود، چه می‌بینی؟","paragraphs":["چیزهایی هست که پیش از واقعی‌شدن، فقط در ذهن کسی جا داشته‌اند. یک دیدار، یک سفر، حتی راهی تازه برای گفتن دوستت دارم.","اگر لازم نبود همین حالا عملی‌بودنِ خیالت را ثابت کنی، چه تصویری به ذهنت می‌آمد؟ آن را برای چند لحظه نگه دار.","خیال شاید نقشه‌ی کامل راه نباشد؛ اما گاهی همان پنجره‌ای است که امکانِ راه را نشانمان می‌دهد."],"audioMedia":null}'::jsonb,'import from 4009b3c70729b832ecaaa1606c49158b3267521e' FROM content_item WHERE stable_key='experience:star' AND NOT EXISTS (SELECT 1 FROM content_revision WHERE item_id=content_item.id) ON CONFLICT (item_id,version) DO NOTHING;
INSERT INTO content_item(kind,stable_key,slug) VALUES ('experience','experience:pause','pause') ON CONFLICT (stable_key) DO NOTHING;
INSERT INTO content_revision(item_id,version,payload,note) SELECT id,1,'{"id":"pause","title":"برای رسیدن، گاهی باید مکث کرد.","short":"یک جای خالی برای خودت.","minutes":7,"format":"listen","question":"دوست داری از کدام شتاب فاصله بگیری؟","paragraphs":["روزها می‌توانند آن‌قدر پُر باشند که برای تجربه‌کردنشان جایی نماند. از کاری به کار دیگر می‌رویم و فراموش می‌کنیم بپرسیم: این شتاب، ما را به کجا می‌برد؟","اگر چند دقیقه هیچ کاری قرار نبود بهترت کند، آن چند دقیقه را چگونه می‌گذراندی؟","این مکث، جایزه‌ی پایان کار نیست. بخشی از زندگی است؛ همان زندگی که قرار بود برایش تلاش کنیم."],"audioMedia":null}'::jsonb,'import from 4009b3c70729b832ecaaa1606c49158b3267521e' FROM content_item WHERE stable_key='experience:pause' AND NOT EXISTS (SELECT 1 FROM content_revision WHERE item_id=content_item.id) ON CONFLICT (item_id,version) DO NOTHING;
INSERT INTO content_item(kind,stable_key,slug) VALUES ('experience','experience:another','another') ON CONFLICT (stable_key) DO NOTHING;
INSERT INTO content_revision(item_id,version,payload,note) SELECT id,1,'{"id":"another","title":"از آن سوی عادت نگاه کن.","short":"یک نگاهِ ناآشنا.","minutes":7,"format":"listen","question":"کدام چیز آشنا را تازه دیدی؟","paragraphs":["آشناشدن، گاهی ما را از دیدن بازمی‌دارد. جمله‌ای را می‌شنویم پیش از آنکه تمام شود. منظره‌ای را می‌شناسیم پیش از آنکه نگاهش کنیم.","امروز یکی از چیزهای معمولی را چنان ببین که انگار اولین بار است. یک دست، یک خیابان، یا چهره‌ی کسی که مدت‌هاست می‌شناسی.","شاید تازگی همیشه جای دیگری نباشد. شاید در شیوه‌ی نگاه‌کردن منتظر ما باشد."],"audioMedia":null}'::jsonb,'import from 4009b3c70729b832ecaaa1606c49158b3267521e' FROM content_item WHERE stable_key='experience:another' AND NOT EXISTS (SELECT 1 FROM content_revision WHERE item_id=content_item.id) ON CONFLICT (item_id,version) DO NOTHING;
